import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws IOException {
        StringBuilder i = new StringBuilder();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int c;
        while ((c = br.read()) != -1) {
            i.append((char) c);
        }
        String EOL = System.lineSeparator();
        String[] lines = i.toString().split(EOL, -1);
        String[] first = lines[0].split(" ");
        String n = first[0];
        String k = first[1];
        System.out.println(getCandiesEaten(Long.parseLong(n.trim()), Long.parseLong(k.trim())));
    }

    static long getCandiesEaten(long n, long k) {
        if (n == 1) return 0;
        n--;
        long candies = 1;
        long sum = 2;
        long consumed = 0;
        while (n > 0) {
            while (candies <= k) {
                candies += sum;
                sum++;
                n--;
            }
            // Reduce candies to less than k
            long candiesToSubtract = candies - k;
            n -= candiesToSubtract;
            consumed += candiesToSubtract;
            candies -= candiesToSubtract;
        }
        return consumed;
    }
}
